let activePaletteIndex;
let random;

function setup() {
  random = new Random();
  let www = 600;
  createCanvas(www, (8/6)*www);
  frameRate(30);
  convergencePointX = width / 2;
  convergencePointY = height / 2;
  // Define the ranges for random values
  numSections = random.random_num(350, 500); // Adjust the range as needed
  textureSize = random.random_num(1, 3); // Adjust the range as needed
  textureSpeed = random.random_num(0.15, 0.15); // Adjust the range as needed
  noiseScale = random.random_num(0.001, 0.01); // Adjust the range as needed
  helixRadius = random.random_num(20, 75); // Adjust the range as needed
  rotationSpeed = random.random_num(0.01, 0.1); // Adjust the range as needed

  // Randomly select a palette
  activePaletteIndex = random.random_int(0, colorPalettes.length-1);

 // Define stroke colors based on probabilities
  let strokeColorString = "";
  let randomValue = random.random_dec();
  if (randomValue < 0.025) {
    strokeColor = color("#FF0000"); // 2.5% red
    strokeColorString = "Red";
  } else if (randomValue < 0.05) {
    strokeColor = color(0, 0, 128); // 2.5% navy (navy is represented as RGB color)
    strokeColorString = "Navy";
  } else if (randomValue < 0.75) {
    strokeColor = color(0); // 70% black
    strokeColorString = "Black";
  } else if (randomValue < 0.95) {
    strokeColor = color(255); // 20% white
    strokeColorString = "White";
  } else {
    strokeColor = color("#FFFDD0"); // 5% red (fallback)
    strokeColorString = "Cream";
  }

  // Randomly select a background color
  randomBackgroundColor = random.random_choice(backgroundColors);
  let smallerDimension = windowWidth < windowHeight ? windowWidth : windowHeight;

  background(randomBackgroundColor);
  textAlign(CENTER);
  text("Loading...",width/2,height/2);
  ((document.getElementsByTagName("canvas")[0].style.width = smallerDimension + "px"),
  (document.getElementsByTagName("canvas")[0].style.height = smallerDimension*(4/3) + "px"),
  (document.getElementsByTagName("canvas")[0].style.position = "absolute"));
}


function draw() {

  let noiseT = frameCount * textureSpeed;
  let twoPI = 2 * PI;
  background(randomBackgroundColor);

  stroke(strokeColor);
  strokeWeight(0.35);
 
  for (let section = 0; section < numSections; section++) {
    let angle = map(section, 0, numSections, -PI, PI);
    let cosAngle = cos(angle);
    let sinAngle = sin(angle);
    let rotationValue = frameCount * rotationSpeed;

    for (let y = 0; y < height; y += textureSize) {
      let cosRotation = cos(rotationValue);
      let sinRotation = sin(rotationValue);
      let distanceFactor = map(y, 0, width / 4, 1.0, 0.1);

      let xA = convergencePointX + cosAngle * helixRadius;
      let zA = convergencePointY + sinAngle * helixRadius;

      let xB = xA;
      let zB = zA;

      let xC = xA;
      let zC = zA;

      let tA = noiseT + (xA + y + zA) * noiseScale;
      let tB = noiseT + (xB + y + zB) * noiseScale;
      let tC = noiseT + (xC + y + zC) * noiseScale;

      let palette = colorPalettes[activePaletteIndex];
      let numColorStops = palette.length;
      let colorIndexA = Math.floor(map(cos(tA), -1, 1, 0, numColorStops - 1));
      let colorIndexB = Math.floor(map(cos(tB), -1, 1, 0, numColorStops - 1));
      let colorIndexC = Math.floor(map(cos(tC), -1, 1, 0, numColorStops - 1));

      let colorA = color(palette[colorIndexA]);
      let colorB = color(palette[colorIndexB]);
      let colorC = color(palette[colorIndexC]);

      let distance = dist(xA, y, convergencePointX, convergencePointY);
      let maxSize = 5;
      let minOpacity = 150;
      let maxOpacity = 255;
      let sizeFactor = map(distance, 0, width / 2, 1.0, 0.1);
      let ellipseSize = sizeFactor * maxSize;
      let opacity = map(distance, 0, width / 2, minOpacity, maxOpacity);

      let rotation = map(distance, 0, width / 2, -PI, PI);
      let zOffset = sin(tA) * random.random_num(100, 150);
      let offsetXA = cos(rotation) * zOffset;
      let offsetYA = sin(rotation) * zOffset;

      fill(colorA);
      ellipse(xA + offsetXA, y + offsetYA, ellipseSize);

      fill(colorB);
      ellipse(xB + offsetXA, y + offsetYA, ellipseSize);

      fill(colorC);
      ellipse(xC + offsetXA, y + offsetYA, ellipseSize);
    }
  }
  noLoop();
}

