function shuffle2(e) {
    for (let n = 0; n < 3; n++)
        for (let t = e.length - 1; t > 0; t--) {
            let s = random.random_int(0, e.length - 1),
                i = e[t],
                $ = e[s];
            (e[t] = $), (e[s] = i);
        }
    return e;
}
